    <label for="indicator">Indicator
      <select id="indicator"></select>
    </label>
    <label for="year">Year
      <select id="year"></select>
    </label>
  </section>

  <section class="card">
    <div class="card-head">
      <h2 id="chart-title"></h2>
      <p id="chart-def"></p>
    </div>
    <div id="bars"></div>
  </section>

  <section class="card">
    <h2>Source &amp; formula</h2>
    <div id="source" class="source-grid"></div>
    <div id="disclaimer"></div>
  </section>
</main>
<footer>Generated by build.py from maternal_health.xlsx - data computed client-side, no external dependencies.</footer>
<script>
const DATA = __DATA__;
const records = DATA.records;
const indicators = DATA.indicators;
const years = DATA.years;

const selInd = document.getElementById("indicator");
const selYear = document.getElementById("year");
const fmt = new Intl.NumberFormat("en-IN");

for (const ind of indicators) selInd.add(new Option(ind.name, ind.name));
for (const y of years) selYear.add(new Option(y, y));
selYear.value = String(years[years.length - 1]);

function currentIndicator() {
  return indicators.find((i) => i.name === selInd.value);
}

function render() {
  const ind = currentIndicator();
  const year = Number(selYear.value);

  const rows = records
    .filter((r) => r.year === year)
    .map((r) => ({
      district: r.district,
      num: r[ind.numerator],
      den: r[ind.denominator],
      value: r[ind.denominator] ? (r[ind.numerator] / r[ind.denominator]) * 100 : null,
    }))
    .sort((a, b) => (b.value === null ? -1 : b.value) - (a.value === null ? -1 : a.value));

  document.getElementById("chart-title").textContent =
    ind.name + " - " + year + " (by district)";
  document.getElementById("chart-def").textContent = ind.definition;

  const bars = document.getElementById("bars");
  bars.innerHTML = "";
  rows.forEach((row, idx) => {
    const el = document.createElement("div");
    el.className = "row";
    el.title = row.district + ": " + fmt.format(row.num) + " " + ind.numerator +
               " / " + fmt.format(row.den) + " " + ind.denominator;
    el.innerHTML =
      '<div class="rank">' + (idx + 1) + "</div>" +
      '<div class="label">' + row.district + "</div>" +
      '<div class="bar-track"><div class="bar" style="width:' +
        (row.value === null ? 0 : Math.min(row.value, 100)) + '%"></div></div>' +
      '<div class="value">' + (row.value === null ? "n/a" : row.value.toFixed(1) + "%") + "</div>" +
      '<div class="raw">' + fmt.format(row.num) + " / " + fmt.format(row.den) + "</div>";
    bars.appendChild(el);
  });

  document.getElementById("source").innerHTML =
    '<div class="field"><div class="k">Indicator</div><div class="v">' + ind.name + "</div></div>" +
    '<div class="field"><div class="k">Definition</div><div class="v">' + ind.definition + "</div></div>" +
    '<div class="field"><div class="k">Formula</div><code class="formula">' + ind.formula + "</code></div>" +
    '<div class="field"><div class="k">Unit</div><div class="v">' + ind.unit + "</div></div>" +
    '<div class="field"><div class="k">Source sheet</div><div class="v">' + DATA.sourceSheet + "</div></div>" +
    '<div class="field"><div class="k">Columns used</div><div class="v">' +
      "district, year, " + ind.numerator + ", " + ind.denominator + "</div></div>" +
    '<div class="field"><div class="k">Workbook</div><div class="v">' + DATA.workbook + "</div></div>" +
    '<div class="field"><div class="k">Data source</div><div class="v">' + ind.source + "</div></div>";

  document.getElementById("disclaimer").innerHTML = DATA.notes
    .map((n) => '<div class="disclaimer"><strong>Important:</strong> ' + n + "</div>")
    .join("");
}

selInd.addEventListener("change", render);
selYear.addEventListener("change", render);
render();
</script>
</body>
</html>
"""


def main():
    wb = openpyxl.load_workbook(WORKBOOK, data_only=True)
    data_header, records = read_district_data(wb)
    indicators, notes = read_indicators(wb)
    if not indicators:
        raise SystemExit("No indicators found in 'Indicator Notes' sheet")

    years = sorted({r["year"] for r in records})
    districts = []
    for r in records:
        if r["district"] not in districts:
            districts.append(r["district"])

    data = {
        "workbook": WORKBOOK.name,
        "sourceSheet": "District Data",
        "dataColumns": data_header,
        "records": records,
        "indicators": indicators,
        "years": years,
        "districts": districts,
        "notes": notes,
    }

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(TEMPLATE.replace("__DATA__", json.dumps(data, indent=2)), encoding="utf-8")
    print(f"Wrote {OUT.relative_to(BASE)} ({OUT.stat().st_size:,} bytes)")
    print(f"  districts : {', '.join(districts)}")
    print(f"  years     : {years}")
    print(f"  indicators: {', '.join(i['name'] for i in indicators)}")


if __name__ == "__main__":
    main()

